# SPDX-License-Identifier: AGPL-3.0-only
def solve(payload):
    cache, answers = {}, []
    for operation in payload:
        now = operation['time']
        cache = {key: item for key, item in cache.items() if item[1] >= now}
        key = operation['key']
        if operation['op'] == 'get':
            answers.append(cache[key][0] if key in cache else None)
        else:
            expires = now + operation['ttl']
            if expires >= now:
                cache[key] = (operation['value'], expires)
            else:
                cache.pop(key, None)
    return {'gets': answers, 'items': [[key, cache[key][0]] for key in sorted(cache)]}

